  if(stage==3){if(++ticks<45)return;check(net.minecraft.client.renderer.OpenGlHelper.shadersSupported,"This Mac exposes the shader capability required by motion blur");Field blur=null;for(Field f:mc.entityRenderer.getClass().getDeclaredFields())if(f.getName().contains("unbox")&&f.getType()==net.minecraft.client.shader.ShaderGroup.class)blur=f;check(blur!=null,"Motion blur pipeline hook is present");blur.setAccessible(true);check(blur.get(mc.entityRenderer)!=null,"Motion blur owns a successfully initialized shader group");check(GL11.glGetError()==0,"Motion blur renders with all six performance components");shot("world-blur");UiState.set("blur",false);mc.displayGuiScreen(new HomeScreen(true));stage=4;ticks=0;return;}
