 private static int viewStep;private static final String[] viewNames={"empty-default","empty-adjusted","sword-default","sword-adjusted","sword-block","bow-draw"};
 private static void configureView(int step){Minecraft mc=Minecraft.getMinecraft();mc.setIngameNotInFocus();mc.thePlayer.rotationPitch=mc.thePlayer.prevRotationPitch=0;mc.thePlayer.rotationYaw=mc.thePlayer.prevRotationYaw=0;mc.thePlayer.stopUsingItem();ItemStack item=step<2?null:new ItemStack(step==5?Items.bow:Items.diamond_sword);mc.thePlayer.inventory.mainInventory[mc.thePlayer.inventory.currentItem]=item;UiState.set("viewmodel",step==1||step>=3);UiState.set("viewmodel.item.x",25);UiState.set("viewmodel.item.y",5);UiState.set("viewmodel.item.z",10);UiState.set("viewmodel.item.scale",65);UiState.set("viewmodel.item.roll",12);UiState.set("viewmodel.separateHand",true);UiState.set("viewmodel.empty.x",15);UiState.set("viewmodel.empty.scale",55);if(step>=4)mc.thePlayer.setItemInUse(item,item.getMaxItemUseDuration());}
 private static void bindFromPanel(ModsScreen screen,String label,int code)throws Exception{for(UiScreen.Control c:screen.controls)if(c.label.equals(label)){c.key((char)0,org.lwjgl.input.Keyboard.KEY_RETURN);screen.keyTyped((char)0,code);return;}throw new IllegalStateException("Missing live key editor "+label);}
 private static void regressionChecks()throws Exception{Minecraft mc=Minecraft.getMinecraft();
  net.minecraft.scoreboard.Scoreboard board=mc.theWorld.getScoreboard();net.minecraft.scoreboard.ScorePlayerTeam team=new net.minecraft.scoreboard.ScorePlayerTeam(board,"UnboxPacketTest");net.minecraft.scoreboard.ScoreObjective objective=new net.minecraft.scoreboard.ScoreObjective(board,"UnboxObjective",net.minecraft.scoreboard.IScoreObjectiveCriteria.DUMMY);
  mc.getNetHandler().handleTeams(new net.minecraft.network.play.server.S3EPacketTeams(team,1));mc.getNetHandler().handleScoreboardObjective(new net.minecraft.network.play.server.S3BPacketScoreboardObjective(objective,1));check(board.getTeam("UnboxPacketTest")==null&&board.getObjective("UnboxObjective")==null,"Missing team/objective removals do not throw on the real packet handler");
  mc.getNetHandler().handleTeams(new net.minecraft.network.play.server.S3EPacketTeams(team,0));mc.getNetHandler().handleScoreboardObjective(new net.minecraft.network.play.server.S3BPacketScoreboardObjective(objective,0));check(board.getTeam("UnboxPacketTest")!=null&&board.getObjective("UnboxObjective")!=null,"Valid server team/objective creation remains intact");
  for(int i=0;i<2;i++){mc.getNetHandler().handleTeams(new net.minecraft.network.play.server.S3EPacketTeams(team,1));mc.getNetHandler().handleScoreboardObjective(new net.minecraft.network.play.server.S3BPacketScoreboardObjective(objective,1));}check(board.getTeam("UnboxPacketTest")==null&&board.getObjective("UnboxObjective")==null&&ExtraHud.objective()!=null,"Valid and repeated removals preserve the unrelated live scoreboard");
  float expected=mc.theWorld.provider.calculateCelestialAngle(6000,0);for(long real:new long[]{0,6000,12000,18000,23999}){mc.theWorld.getWorldInfo().setWorldTime(real);for(float partial:new float[]{0,.25f,.75f,1})check(Math.abs(mc.theWorld.getCelestialAngle(partial)-mc.theWorld.provider.calculateCelestialAngle(6000,partial))<.00001f,"Sky angle uses visual time at real time "+real+" / "+partial);}
  check(mc.theWorld.getSunBrightness(0)>.8f,"Daytime keeps daylight brightness when real time is night");
  int[] before=new int[mc.gameSettings.keyBindings.length];for(int i=0;i<before.length;i++)before[i]=mc.gameSettings.keyBindings[i].getKeyCode();int occupied=UiKeys.binding("lookback").getKeyCode();ModsScreen keyScreen=new ModsScreen(null);mc.displayGuiScreen(keyScreen);keyScreen.openDetail("zoom");bindFromPanel(keyScreen,"Change Activation key",occupied);check(UiKeys.binding("zoom").getKeyCode()==occupied&&UiKeys.binding("lookback").getKeyCode()==0,"New activation binding replaces the occupied binding");keyScreen.openDetail("hitcolor");bindFromPanel(keyScreen,"Change Toggle module",occupied);check(UiKeys.binding("zoom").getKeyCode()==0&&UiKeys.binding("hitcolor.toggle").getKeyCode()==occupied,"Module toggle keys share the same conflict replacement");mc.gameSettings.loadOptions();check(UiKeys.binding("hitcolor.toggle").getKeyCode()==occupied&&UiKeys.binding("zoom").getKeyCode()==0,"Panel key changes survive options reload");mc.displayGuiScreen(null);for(int i=0;i<before.length;i++)mc.gameSettings.keyBindings[i].setKeyCode(before[i]);net.minecraft.client.settings.KeyBinding.resetKeyBindingArrayAndHash();mc.gameSettings.saveOptions();
  Object mod=net.minecraftforge.fml.common.Loader.instance().getIndexedModList().get("unpvp").getMod();Field f=Unpvp.class.getDeclaredField("pvp");f.setAccessible(true);PvpControls controls=(PvpControls)f.get(mod);Field sprint=PvpControls.class.getDeclaredField("sprinting"),world=PvpControls.class.getDeclaredField("world");sprint.setAccessible(true);world.setAccessible(true);sprint.setBoolean(controls,true);world.set(controls,mc.theWorld);mc.displayGuiScreen(new HomeScreen(true));controls.tick();check(sprint.getBoolean(controls),"Opening the UI preserves toggled sprint intent");mc.displayGuiScreen(null);mc.inGameHasFocus=true;mc.thePlayer.movementInput.moveForward=1;mc.thePlayer.setSprinting(false);controls.tick();check(sprint.getBoolean(controls)&&mc.thePlayer.isSprinting(),"Closing the UI resumes sprint while moving");sprint.setBoolean(controls,false);mc.thePlayer.movementInput.moveForward=0;mc.thePlayer.setSprinting(false);mc.setIngameNotInFocus();
 }
 private static void tintCheck()throws Exception{Minecraft mc=Minecraft.getMinecraft();RendererLivingEntity renderer=(RendererLivingEntity)mc.getRenderManager().getEntityRenderObject(mc.thePlayer);Method set=null,unset=null;Field buffer=null;for(Method m:RendererLivingEntity.class.getDeclaredMethods()){if(m.getName().equals("setBrightness")||m.getName().equals("func_177092_a"))set=m;if(m.getName().equals("unsetBrightness")||m.getName().equals("func_177091_f"))unset=m;}for(Field f:RendererLivingEntity.class.getDeclaredFields())if(f.getType()==FloatBuffer.class)buffer=f;if(set==null||unset==null||buffer==null)throw new IllegalStateException("Missing damage renderer probe");set.setAccessible(true);unset.setAccessible(true);buffer.setAccessible(true);int old=mc.thePlayer.hurtTime;try{mc.thePlayer.hurtTime=5;set.invoke(renderer,mc.thePlayer,0f,true);FloatBuffer values=(FloatBuffer)buffer.get(renderer);check(values.get(0)==0&&values.get(1)==1&&values.get(2)==0,"Hit Color changes the actual living-entity hurt overlay");}finally{unset.invoke(renderer);mc.thePlayer.hurtTime=old;}}
 private static void check(boolean good,String message){if(!good)throw new IllegalStateException(message);checks++;System.out.println("[unpvp-pvp-check] "+message);}
 private static void shot(String name){Minecraft mc=Minecraft.getMinecraft();File dir=new File(mc.mcDataDir,"pvp-probe");dir.mkdirs();ScreenShotHelper.saveScreenshot(dir,name+".png",mc.displayWidth,mc.displayHeight,mc.getFramebuffer());}
